const STAGES = M.stage_order;
const fmt = n => n == null ? '—' : n.toLocaleString('en');
const esc = s => String(s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const sc = s => `var(--s-${s})`;

/* ---------- derived once, never typed ---------- */
const maxRows = Math.max(...D.tables.map(t => t.rows));
const liveEdges = D.edges.filter(e => e.nn > 0);
const declaredIdle = D.edges.filter(e => e.nn === 0);
const deadEdges = D.edges.filter(e => e.dead && e.child > 0);
const orphanEdges = D.edges.filter(e => e.orph > 0);
const noWriter = D.tables.filter(t => !t.writers.length && !t.internal);
const unwritable = D.tables.filter(t => t.unwritable.length);
const emptyT = D.tables.filter(t => t.rows === 0);
const byStage = s => D.tables.filter(t => t.stage === s);
const stageRows = s => byStage(s).reduce((a, t) => a + t.rows, 0);
const totalResolved = liveEdges.reduce((a, e) => a + e.res, 0);
const totalPointers = liveEdges.reduce((a, e) => a + e.nn, 0);

/* value indexes for the row walker, built lazily */
const IDX = {};
function idx(table, col) {
  const k = table + '.' + col;
  if (IDX[k]) return IDX[k];
  const t = T[table], ci = t.cols.findIndex(c => c.n === col), m = new Map();
  if (ci >= 0) (D.data[table] || []).forEach((r, i) => {
    const v = r[ci]; if (v == null) return;
    const key = String(v);
    if (!m.has(key)) m.set(key, []);
    m.get(key).push(i);
  });
  return IDX[k] = m;
}
const colIdx = (table, col) => T[table].cols.findIndex(c => c.n === col);
function label(table, i) {
  const t = T[table], r = (D.data[table] || [])[i];
  if (!r) return '?';
  const pk = t.pk.length ? t.pk : [t.cols[0].n];
  const head = pk.map(p => r[colIdx(table, p)]).join(' · ');
  const nice = t.cols.find(c => /name|title|label|canonical|slug|query|statement|value/i.test(c.n)
    && typeof r[colIdx(table, c.n)] === 'string' && r[colIdx(table, c.n)]);
  return head + (nice ? ' — ' + String(r[colIdx(table, nice.n)]).slice(0, 72) : '');
}

/* ---------- chrome ---------- */
document.getElementById('fp').innerHTML = `
  <span><b>${esc(M.db)}</b></span>
  <span>sha <b>${esc(M.sha256)}</b></span>
  <span>schema <b>v${M.user_version}</b></span>
  <span>as of <b>${esc(M.asof || '—')}</b></span>`;

const VIEWS = [
  ['atlas', 'Atlas'], ['walk', 'Walkability'], ['batches', 'Batches'],
  ['writers', 'Writers'], ['views', 'Views']
];
const tabs = document.getElementById('tabs');
tabs.innerHTML = VIEWS.map(([id, lab]) =>
  `<button class="tab" role="tab" id="tab-${id}" aria-selected="false" data-v="${id}">${lab}</button>`).join('');
tabs.addEventListener('click', e => {
  const b = e.target.closest('.tab'); if (b) show(b.dataset.v);
});

function show(v) {
  [...tabs.children].forEach(b => b.setAttribute('aria-selected', String(b.dataset.v === v)));
  document.getElementById('main').innerHTML = RENDER[v]();
  WIRE[v] && WIRE[v]();
  window.scrollTo({ top: 0 });
}

/* ---------- tiles ---------- */
function tiles(list) {
  return `<div class="tiles">${list.map(t => `<div class="tile">
    <div class="v" ${t.tone ? `style="color:${t.tone}"` : ''}>${t.v}</div>
    <div class="k">${t.k}</div>${t.sub ? `<div class="sub">${t.sub}</div>` : ''}
  </div>`).join('')}</div>`;
}

/* ---------- ATLAS ---------- */
const RENDER = {}, WIRE = {};

RENDER.atlas = () => {
  let h = tiles([
    { v: fmt(M.rows), k: 'rows held', sub: `across ${M.tables} tables` },
    { v: fmt(D.tables.length - emptyT.length), k: 'tables with rows', sub: `${emptyT.length} still empty` },
    { v: fmt(D.sessions.length), k: 'batches', sub: 'distinct writing sessions' },
    { v: fmt(M.edges), k: 'declared pointers', sub: `${liveEdges.length} carry rows` },
    { v: fmt(noWriter.length), k: 'tables no tool writes', tone: noWriter.length ? 'var(--crit)' : '', sub: 'derived from the scripts tree' },
    { v: fmt(unwritable.length), k: 'unwritable tables', tone: unwritable.length ? 'var(--crit)' : '', sub: 'NOT NULL FK into an empty table' }
  ]);

  h += `<div class="section"><h2>Every table, in spine order</h2>
    <p class="lede">The seven pipeline stages in the order the spine runs them, then the tables that
    record the repository's own operation. Row count, the tools that can write it, and what is
    blocking it. Select any table to read its rows and walk its pointers.</p>
    <div class="controls">
      <input type="search" id="q" placeholder="filter tables, columns, writers…" aria-label="Filter tables">
      <button class="btn" id="f-nonempty" aria-pressed="false">only tables with rows</button>
      <button class="btn" id="f-blocked" aria-pressed="false">only blocked</button>
    </div><div id="atlaslist"></div></div>`;
  return h;
};

function atlasList() {
  const q = (document.getElementById('q')?.value || '').toLowerCase();
  const nonEmpty = document.getElementById('f-nonempty')?.getAttribute('aria-pressed') === 'true';
  const blocked = document.getElementById('f-blocked')?.getAttribute('aria-pressed') === 'true';
  let out = '';
  for (const s of STAGES) {
    let ts = byStage(s);
    if (!ts.length) continue;
    ts = ts.filter(t => {
      if (nonEmpty && !t.rows) return false;
      if (blocked && !(t.unwritable.length || !t.writers.length)) return false;
      if (!q) return true;
      return t.name.includes(q) || t.cols.some(c => c.n.includes(q))
        || t.writers.some(w => w.tool.toLowerCase().includes(q));
    });
    if (!ts.length) continue;
    ts.sort((a, b) => b.rows - a.rows || a.name.localeCompare(b.name));
    const rows = ts.reduce((a, t) => a + t.rows, 0);
    out += `<div class="stagehead"><i class="dot" style="background:${sc(s)}"></i>
      <span class="stagename" style="color:${sc(s)}">${s}</span>
      <span class="stagemeta">${ts.length} tables · ${fmt(rows)} rows</span></div>`;
    out += ts.map(t => {
      const w = t.writers.length
        ? [...new Set(t.writers.filter(x => x.kind === 'cli').map(x => x.tool))].slice(0, 2)
            .map(x => `<span class="chip cli">${esc(x)}</span>`).join('')
          + (t.writers.some(x => x.kind === 'script')
            ? `<span class="chip script">${[...new Set(t.writers.filter(x => x.kind === 'script').map(x => x.tool.split('/').pop()))].slice(0, 1)}</span>` : '')
          + (t.writers.some(x => x.kind === 'migration') && !t.writers.some(x => x.kind === 'cli')
            ? `<span class="chip mig">migration only</span>` : '')
        : `<span class="chip none">no writer</span>`;
      const flags = [
        t.unwritable.length ? `<span class="flag unw" title="NOT NULL FK into an empty table">unwritable</span>` : '',
        !t.rows && !t.unwritable.length ? `<span class="flag empty">empty</span>` : '',
        !t.writers.length && !t.internal && !t.unwritable.length ? `<span class="flag nw">no writer</span>` : ''
      ].join('');
      const pct = maxRows ? Math.max(t.rows ? 1.5 : 0, (t.rows / maxRows) * 100) : 0;
      return `<button class="trow ${t.rows ? '' : 'is-empty'}" data-t="${t.name}">
        <span class="tname">${esc(t.name)}</span>
        <span class="tcount ${t.rows ? '' : 'z'}">${fmt(t.rows)}</span>
        <span class="bar"><i style="width:${pct}%;background:${sc(s)}"></i></span>
        <span class="wchips">${w}</span>
        <span class="flags">${flags}</span></button>`;
    }).join('');
  }
  document.getElementById('atlaslist').innerHTML = out || `<p class="note">Nothing matches that filter.</p>`;
}

WIRE.atlas = () => {
  atlasList();
  document.getElementById('q').addEventListener('input', atlasList);
  for (const id of ['f-nonempty', 'f-blocked']) {
    document.getElementById(id).addEventListener('click', e => {
      const b = e.currentTarget;
      b.setAttribute('aria-pressed', b.getAttribute('aria-pressed') === 'true' ? 'false' : 'true');
      atlasList();
    });
  }
  document.getElementById('atlaslist').addEventListener('click', e => {
    const b = e.target.closest('.trow'); if (b) openTable(b.dataset.t);
  });
};

/* ---------- WALKABILITY ---------- */
RENDER.walk = () => {
  const rate = totalPointers ? Math.round(totalResolved / totalPointers * 1000) / 10 : 0;
  let h = tiles([
    { v: fmt(M.edges), k: 'declared pointers', sub: 'foreign keys in the schema' },
    { v: fmt(liveEdges.length), k: 'carrying rows', sub: `${declaredIdle.length} declared but unused` },
    { v: rate + '%', k: 'pointers that resolve', tone: rate === 100 ? 'var(--accent)' : 'var(--crit)', sub: `${fmt(totalResolved)} of ${fmt(totalPointers)} values` },
    { v: fmt(orphanEdges.length), k: 'orphan-bearing edges', tone: orphanEdges.length ? 'var(--crit)' : 'var(--accent)', sub: 'values pointing at nothing' },
    { v: fmt(deadEdges.length), k: 'pointers into empty', tone: deadEdges.length ? 'var(--crit)' : '', sub: 'target table holds no rows' },
    { v: fmt(D.views.filter(v => v.crosses).length), k: 'cross-stage views', sub: `of ${D.views.length} views` }
  ]);

  h += `<div class="section"><h2>The graph</h2>
    <p class="lede">Every table placed in its pipeline stage, every foreign key drawn between them.
    A solid line carries rows today; a faint line is declared in the schema but no row uses it yet;
    a red line points into a table that holds nothing, so the walk stops there.</p>
    <div class="controls">
      <button class="btn" id="g-live" aria-pressed="true">only edges carrying rows</button>
      <button class="btn" id="g-nonempty" aria-pressed="true">hide empty tables</button>
    </div>
    <div class="graphbox" id="graph"></div>
    <div class="legend">
      <span><i class="lswatch" style="background:var(--accent)"></i> carries rows</span>
      <span><i class="lswatch" style="background:var(--ink3);opacity:.5"></i> declared, unused</span>
      <span><i class="lswatch" style="background:var(--crit)"></i> target table empty</span>
    </div></div>`;

  h += `<div class="section"><h2>Walk a row</h2>
    <p class="lede">Pick a table and a row, then follow its pointers outward. Upward is what this row
    points at; downward is everything that points back at it. This is the walk rule 5 is about —
    a fact stays in one place and is reached, never copied.</p>
    <div class="controls">
      <select id="wt" aria-label="Table to walk"></select>
      <select id="wr" aria-label="Row to walk"></select>
    </div>
    <div class="crumbs" id="crumbs"></div>
    <div id="walkout"></div></div>`;

  h += `<div class="section"><h2>Pointer integrity, edge by edge</h2>
    <p class="lede">Measured against the live rows, not declared. <b>Set</b> counts rows whose pointer
    is filled in; <b>lands</b> counts those that reach a real parent row; <b>orphan</b> is the difference.</p>
    <div class="controls"><input type="search" id="eq" placeholder="filter edges…" aria-label="Filter edges"></div>
    <div class="scroll"><div id="edgelist"></div></div></div>`;
  return h;
};

function drawGraph() {
  const onlyLive = document.getElementById('g-live').getAttribute('aria-pressed') === 'true';
  const hideEmpty = document.getElementById('g-nonempty').getAttribute('aria-pressed') === 'true';
  let edges = D.edges.filter(e => e.src !== e.dst);
  if (onlyLive) edges = edges.filter(e => e.nn > 0 || (e.dead && e.child > 0));
  const keep = new Set();
  edges.forEach(e => { keep.add(e.src); keep.add(e.dst); });
  const cols = STAGES.map(s => ({
    s, ts: byStage(s).filter(t => (!hideEmpty || t.rows > 0) && keep.has(t.name))
                     .sort((a, b) => b.rows - a.rows)
  })).filter(c => c.ts.length);

  const CW = 190, RH = 21, TOP = 40, PAD = 14;
  const H = TOP + Math.max(...cols.map(c => c.ts.length)) * RH + 30;
  const W = cols.length * CW + PAD * 2;
  const pos = {};
  cols.forEach((c, ci) => c.ts.forEach((t, ri) => {
    pos[t.name] = { x: PAD + ci * CW, y: TOP + ri * RH + 10, w: CW - 30, s: c.s, ci };
  }));

  let svg = `<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" role="img"
    aria-label="Foreign key graph by pipeline stage">`;
  cols.forEach((c, ci) => {
    svg += `<text class="colhead" x="${PAD + ci * CW}" y="22" fill="${sc(c.s)}">${c.s.toUpperCase()}</text>
      <line x1="${PAD + ci * CW}" y1="28" x2="${PAD + ci * CW + CW - 30}" y2="28"
        stroke="${sc(c.s)}" stroke-width="1.5" opacity=".55"/>`;
  });
  const drawn = edges.filter(e => pos[e.src] && pos[e.dst]);
  for (const e of drawn) {
    const a = pos[e.src], b = pos[e.dst];
    const ax = a.x + (b.ci >= a.ci ? a.w : 0), bx = b.x + (b.ci > a.ci ? 0 : b.w);
    const dx = Math.max(24, Math.abs(bx - ax) * .45);
    const col = e.dead ? 'var(--crit)' : (e.nn > 0 ? 'var(--accent)' : 'var(--ink3)');
    const op = e.dead ? .75 : (e.nn > 0 ? .42 : .16);
    svg += `<path d="M${ax},${a.y} C${ax + dx},${a.y} ${bx - dx},${b.y} ${bx},${b.y}"
      fill="none" stroke="${col}" stroke-width="${e.dead ? 1.4 : 1}" opacity="${op}"
      data-src="${e.src}" data-dst="${e.dst}" class="ed"><title>${esc(e.src)}.${esc(e.col)} → ${esc(e.dst)}.${esc(e.dcol)} — ${fmt(e.nn)} set, ${fmt(e.res)} land</title></path>`;
  }
  for (const [n, p] of Object.entries(pos)) {
    const t = T[n];
    svg += `<g class="node" data-t="${n}" style="cursor:pointer">
      <rect x="${p.x - 3}" y="${p.y - 8}" width="${p.w + 6}" height="16" fill="transparent"/>
      <circle cx="${p.x}" cy="${p.y}" r="${t.rows ? 3.2 : 2}" fill="${t.rows ? sc(p.s) : 'none'}"
        stroke="${sc(p.s)}" stroke-width="1"/>
      <text class="nodelabel" x="${p.x + 7}" y="${p.y + 3.2}">${esc(n.length > 23 ? n.slice(0, 22) + '…' : n)}</text>
      <title>${esc(n)} — ${fmt(t.rows)} rows</title></g>`;
  }
  svg += `</svg>`;
  document.getElementById('graph').innerHTML = svg;
  document.getElementById('graph').querySelectorAll('.node').forEach(g =>
    g.addEventListener('click', () => openTable(g.dataset.t)));
}

function edgeList() {
  const q = (document.getElementById('eq')?.value || '').toLowerCase();
  const es = D.edges.filter(e => !q || (e.src + e.col + e.dst + e.dcol).toLowerCase().includes(q))
    .sort((a, b) => b.nn - a.nn || a.src.localeCompare(b.src));
  document.getElementById('edgelist').innerHTML =
    `<div class="edgerow head"><span>from</span><span>to</span><span class="r">set</span>
      <span class="r">lands</span><span class="r">orphan</span><span></span></div>` +
    es.map(e => {
      const state = e.orph ? `<span class="flag unw">orphans</span>`
        : e.dead && e.child ? `<span class="flag unw">target empty</span>`
        : e.nn ? `<span class="flag" style="background:var(--accent-soft);color:var(--accent)">walkable</span>`
        : `<span class="flag empty">unused</span>`;
      return `<div class="edgerow">
        <span><b style="color:${sc(e.sstage)}">${esc(e.src)}</b>.${esc(e.col)}</span>
        <span style="color:var(--ink3)">→ <b style="color:${sc(e.dstage)}">${esc(e.dst)}</b>.${esc(e.dcol)}</span>
        <span class="r">${fmt(e.nn)}</span><span class="r">${fmt(e.res)}</span>
        <span class="r" style="${e.orph ? 'color:var(--crit)' : 'color:var(--ink3)'}">${fmt(e.orph)}</span>
        <span style="text-align:right">${state}</span></div>`;
    }).join('');
}

/* row walker */
let WALK = { t: null, i: 0, trail: [] };
function walkTables() {
  return D.tables.filter(t => t.rows > 0 && !t.internal)
    .sort((a, b) => a.name.localeCompare(b.name));
}
function fillRows() {
  const t = WALK.t, sel = document.getElementById('wr');
  const rows = D.data[t] || [];
  const cap = Math.min(rows.length, 400);
  sel.innerHTML = rows.slice(0, cap).map((_, i) =>
    `<option value="${i}">${esc(label(t, i).slice(0, 84))}</option>`).join('')
    + (rows.length > cap ? `<option disabled>… ${fmt(rows.length - cap)} more — open the table to reach them</option>` : '');
  sel.value = String(Math.min(WALK.i, cap - 1));
}
function renderWalk() {
  const t = WALK.t, i = WALK.i, tm = T[t], row = (D.data[t] || [])[i];
  if (!row) { document.getElementById('walkout').innerHTML = ''; return; }

  const ups = [];
  for (const c of tm.cols) {
    if (!c.fk) continue;
    const v = row[colIdx(t, c.n)];
    if (v == null) { ups.push({ col: c.n, to: c.fk[0], state: 'null' }); continue; }
    const hits = idx(c.fk[0], c.fk[1]).get(String(v)) || [];
    ups.push({ col: c.n, to: c.fk[0], tcol: c.fk[1], v, hits, state: hits.length ? 'ok' : 'orphan' });
  }
  const downs = [];
  for (const e of D.edges) {
    if (e.dst !== t || e.src === t) continue;
    const v = row[colIdx(t, e.dcol)];
    if (v == null) continue;
    const hits = idx(e.src, e.col).get(String(v)) || [];
    if (hits.length) downs.push({ from: e.src, col: e.col, hits });
  }

  const cells = tm.cols.map(c => {
    const v = row[colIdx(t, c.n)];
    return `<div style="font-family:var(--mono);font-size:11px;padding:2px 0;
      border-bottom:1px solid var(--rule);display:flex;gap:10px">
      <span style="color:var(--ink3);min-width:170px">${esc(c.n)}</span>
      <span style="${v == null ? 'color:var(--ink3);font-style:italic' : ''}">${v == null ? 'null' : esc(String(v)).slice(0, 220)}</span></div>`;
  }).join('');

  document.getElementById('walkout').innerHTML = `
    <div class="walkgrid">
      <div class="walkcard"><h4>Points at — ${ups.filter(u => u.state === 'ok').length} of ${ups.length} resolve</h4>
        ${ups.length ? ups.map(u => u.state === 'null'
          ? `<div class="reln"><div class="relhead" style="color:var(--ink3)">${esc(u.col)} → ${esc(u.to)}</div>
             <div style="font-family:var(--mono);font-size:11px;color:var(--ink3);padding-left:10px">not set</div></div>`
          : `<div class="reln"><div class="relhead">${esc(u.col)} → ${esc(u.to)}</div>
             ${u.hits.length ? u.hits.slice(0, 4).map(h =>
               `<div class="relrow" data-t="${u.to}" data-i="${h}">${esc(label(u.to, h))}</div>`).join('')
             : `<div style="font-family:var(--mono);font-size:11px;color:var(--crit);padding-left:10px">orphan — ${esc(String(u.v))} reaches nothing</div>`}</div>`
        ).join('') : `<p class="note" style="margin:0">This table points at nothing — it is a root.</p>`}
      </div>
      <div class="walkcard"><h4>Pointed at by — ${downs.reduce((a, d) => a + d.hits.length, 0)} rows</h4>
        ${downs.length ? downs.map(d => `<div class="reln">
          <div class="relhead">${esc(d.from)}.${esc(d.col)} — ${fmt(d.hits.length)}</div>
          ${d.hits.slice(0, 4).map(h => `<div class="relrow" data-t="${d.from}" data-i="${h}">${esc(label(d.from, h))}</div>`).join('')}
          ${d.hits.length > 4 ? `<div style="font-family:var(--mono);font-size:10.5px;color:var(--ink3);padding-left:10px">+${fmt(d.hits.length - 4)} more</div>` : ''}
        </div>`).join('') : `<p class="note" style="margin:0">Nothing points back at this row yet.</p>`}
      </div>
    </div>
    <div class="walkcard" style="margin-top:14px"><h4>${esc(t)} — this row in full</h4>${cells}</div>`;

  document.getElementById('crumbs').innerHTML = WALK.trail.map((s, n) =>
    `<span class="crumb ${n === WALK.trail.length - 1 ? 'now' : ''}" data-n="${n}">${esc(s.t)} · ${esc(label(s.t, s.i).slice(0, 34))}</span>`).join('<span style="color:var(--ink3)">→</span>');

  document.querySelectorAll('#walkout .relrow').forEach(el => el.addEventListener('click', () => {
    goWalk(el.dataset.t, +el.dataset.i, true);
  }));
  document.querySelectorAll('#crumbs .crumb').forEach(el => el.addEventListener('click', () => {
    const n = +el.dataset.n, s = WALK.trail[n];
    WALK.trail = WALK.trail.slice(0, n + 1);
    WALK.t = s.t; WALK.i = s.i;
    document.getElementById('wt').value = s.t; fillRows();
    document.getElementById('wr').value = String(s.i);
    renderWalk();
  }));
}
function goWalk(t, i, push) {
  WALK.t = t; WALK.i = i;
  if (push) WALK.trail.push({ t, i }); else WALK.trail = [{ t, i }];
  if (WALK.trail.length > 8) WALK.trail = WALK.trail.slice(-8);
  document.getElementById('wt').value = t; fillRows();
  document.getElementById('wr').value = String(i);
  renderWalk();
}

WIRE.walk = () => {
  for (const id of ['g-live', 'g-nonempty'])
    document.getElementById(id).addEventListener('click', e => {
      const b = e.currentTarget;
      b.setAttribute('aria-pressed', b.getAttribute('aria-pressed') === 'true' ? 'false' : 'true');
      drawGraph();
    });
  drawGraph();
  edgeList();
  document.getElementById('eq').addEventListener('input', edgeList);

  const wt = document.getElementById('wt');
  wt.innerHTML = walkTables().map(t => `<option value="${t.name}">${t.name} (${fmt(t.rows)})</option>`).join('');
  // Open on the deepest thing the pipeline has produced, so the first look shows a
  // real walk rather than an empty control.
  const start = T['specifications']?.rows ? 'specifications' : walkTables()[0].name;
  wt.value = start;
  WALK.t = start; WALK.i = 0; fillRows();
  goWalk(start, 0, false);
  wt.addEventListener('change', () => { WALK.i = 0; goWalk(wt.value, 0, false); });
  document.getElementById('wr').addEventListener('change', e => goWalk(WALK.t, +e.target.value, false));
};

/* ---------- BATCHES ---------- */
RENDER.batches = () => {
  const ss = D.sessions;
  const attributed = ss.filter(s => !s.id.startsWith('—')).reduce((a, s) => a + s.rows, 0);
  const unattr = ss.filter(s => s.id.startsWith('—')).reduce((a, s) => a + s.rows, 0);
  const research = ss.filter(s => /research-batch/.test(s.id));
  let h = tiles([
