import time, sys, ast, pathlib, re
sys.path.insert(0, 'tools')
import data_atlas as da
ROOT = da.ROOT

paths = sorted(ROOT.glob('scripts/**/*.py')) + sorted(ROOT.glob('tools/**/*.py'))
modules = {}
for p in paths:
    try:
        tree = ast.parse(p.read_text(encoding='utf-8', errors='replace'))
    except SyntaxError:
        continue
    funcs = {}
    for n in ast.walk(tree):
        if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)):
            funcs[n.name] = (da._sql_writes(n), da._called(n))
    modules[p] = funcs

index = {}
for p, funcs in modules.items():
    for name in funcs:
        index.setdefault(name, []).append(p)

print('total function names (unique):', len(index))
print('total function defs:', sum(len(f) for f in modules.values()))

call_counter = {}
def resolve(fname, seen=None):
    call_counter[fname] = call_counter.get(fname, 0) + 1
    if seen is None:
        seen = set()
    if fname in seen:
        return set()
    seen.add(fname)
    out = set()
    for p in index.get(fname, []):
        direct, calls = modules[p][fname]
        out |= direct
        for c in calls:
            out |= resolve(c, seen)
    return out

# db.py subcommands
dbpy = ROOT / 'scripts/db.py'
tree = ast.parse(dbpy.read_text(encoding='utf-8', errors='replace'))
main = next((n for n in ast.walk(tree) if isinstance(n, ast.FunctionDef) and n.name == 'main'), None)

t0=time.time()
cmd_writes = {}
def walk_if(node):
    if not isinstance(node, ast.If):
        return
    names = []
    for c in ast.walk(node.test):
        if (isinstance(c, ast.Compare) and isinstance(c.left, ast.Attribute) and c.left.attr == 'command'):
            for comp in c.comparators:
                if isinstance(comp, ast.Constant):
                    names.append(comp.value)
                elif isinstance(comp, (ast.List, ast.Tuple)):
                    names += [e.value for e in comp.elts if isinstance(e, ast.Constant)]
    if names:
        body = ast.Module(body=node.body, type_ignores=[])
        w = da._sql_writes(body)
        for c in da._called(body):
            w |= resolve(c)
        for nm in names:
            cmd_writes.setdefault(nm, set()).update(w)
    for o in node.orelse:
        walk_if(o)

if main:
    for n in main.body:
        walk_if(n)
t1=time.time()
print('walk_if + resolve total time:', t1-t0)
print('total resolve() invocations:', sum(call_counter.values()))
print('unique fnames resolved:', len(call_counter))
top = sorted(call_counter.items(), key=lambda kv: -kv[1])[:15]
print('top repeated fnames (fname, call count):')
for k,v in top:
    print(' ', k, v)
